INSERT INTO public.public_site_pages(slug,title,eyebrow,description,sections,published) VALUES('cookies','Cookie Notice','BUSINESSOS · COOKIE INFORMATION','Find out which cookies BusinessOS uses and how to manage your preferences.','[{"heading":"Essential account and security cookies","body":"BusinessOS uses necessary cookies to help keep your account signed in, maintain sessions, protect requests and remember your choices. These are required for the service to operate correctly and cannot be switched off using the Cookie Settings panel. Browser settings may allow you to remove them, but doing so can sign you out or prevent parts of BusinessOS from working."},{"heading":"Your cookie-notice choice","body":"When you select Necessary only or save preferences, BusinessOS records the decision using a first-party cookie named businessos_cookie_notice_v3. The notice is normally remembered for up to 180 days on the same browser. You can reopen Cookie Settings from the website footer or Privacy choices button and save a new choice."},{"heading":"Optional visual preferences","body":"If you enable Reduce decorative motion under Visual preferences and save your choice, BusinessOS stores a first-party preference cookie named businessos_visual_motion_v1 for up to 180 days. That preference reduces animated public-site hero effects. You can switch it off or select Necessary only to remove that cookie. Your device''s Reduced Motion setting is also respected independently."},{"heading":"Analytics and advertising","body":"The current public website does not activate optional analytics or advertising tracking cookies through the BusinessOS cookie-preferences system. There are therefore no analytics or marketing consent switches to enable. If optional tracking is introduced in the future, BusinessOS must update this notice and obtain the necessary choices before those technologies are activated."},{"heading":"Managing and deleting cookies","body":"You can review and revise functional preferences at any time using Cookie Settings in the footer or Privacy choices on a public page. You may also delete cookies using your browser settings. Deleting essential cookies can end your login session. The site will ask you to acknowledge the notice again when a new notice version is released or your saved notice expires."},{"heading":"Questions or changes","body":"Cookie behavior may change when new BusinessOS features are introduced. We will update this page to describe material changes. For questions about your information or to make a privacy request, use the BusinessOS Privacy Notice and the official Contact page."}]'::jsonb,true);
COMMIT;